<?php
if (session_status() === PHP_SESSION_NONE) session_start();
function cc_chat_h($v){return htmlspecialchars((string)$v, ENT_QUOTES, 'UTF-8');}
$c=$data['contrato']??[]; $uid=(int)($data['uid']??0); $mensajes=$data['mensajes']??[];
$esCliente=$uid===(int)($c['cliente_id']??0);
$otro=$esCliente?trim(($c['contador_nombre']??'').' '.($c['contador_apellido']??'')):trim(($c['cliente_nombre']??'').' '.($c['cliente_apellido']??''));
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Chat privado | CreaContable</title><link rel="stylesheet" href="<?php echo URLROOT; ?>/public/css/style.css"><link rel="stylesheet" href="<?php echo URLROOT; ?>/public/css/theme.css"><style>
:root{--gold:#f5a623;--bg:#0b0d12;--card:#151923;--line:#2b3242;--muted:#aab3c5;--ink:#f4f6fb}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--ink);font-family:Segoe UI,Arial,sans-serif}.top{position:sticky;top:0;background:#11151e;border-bottom:1px solid var(--line);padding:12px max(18px,calc((100vw - 1050px)/2));display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap}.brand{font-weight:800;color:var(--ink);text-decoration:none}.brand span{color:var(--gold)}.btn{display:inline-flex;padding:9px 12px;border-radius:8px;text-decoration:none;border:1px solid #3a4355;background:#252c3a;color:var(--ink);font-weight:700}.wrap{max-width:950px;width:94%;margin:25px auto}.heading,.chatbox{background:var(--card);border:1px solid var(--line);border-radius:14px;padding:20px;margin-bottom:15px}.muted{color:var(--muted)}.messages{display:flex;flex-direction:column;gap:10px;max-height:55vh;overflow:auto;padding:5px}.msg{max-width:82%;padding:12px 14px;border:1px solid var(--line);background:#202635;border-radius:12px;align-self:flex-start;overflow-wrap:anywhere}.msg.mine{align-self:flex-end;background:#44351d;border-color:#8a611d}.msg small{display:block;color:var(--muted);margin-top:7px}.field textarea{width:100%;min-height:95px;padding:12px;border-radius:9px;background:#0e1118;border:1px solid #353e50;color:var(--ink);font:inherit;resize:vertical}.send{background:var(--gold);color:#17130a;border:0;border-radius:9px;padding:11px 16px;font-weight:800;cursor:pointer;margin-top:10px}@media(max-width:560px){.msg{max-width:95%}.heading,.chatbox{padding:14px}}
</style></head><body>
<header class="top"><a class="brand" href="<?php echo URLROOT; ?>/marketplace/servicios">🧮 Crea<span>Contable</span></a><nav><a class="btn" href="<?php echo URLROOT; ?>/marketplace/servicios">← Volver al Centro de servicios</a></nav></header>
<main class="wrap"><section class="heading"><h1 style="margin:0 0 8px">Chat privado con <?php echo cc_chat_h($otro); ?></h1><p class="muted" style="margin:0">Contratación #<?php echo (int)$c['id']; ?> · <?php echo cc_chat_h($c['titulo']); ?> · Valor: $<?php echo number_format((float)$c['monto'],0,',','.'); ?> COP</p><p class="muted">Este chat solo es visible para el cliente y el contador asociados a esta contratación.</p></section>
<?php if(!empty($_SESSION['marketplace_msg'])): ?><p class="heading"><?php echo cc_chat_h($_SESSION['marketplace_msg']); unset($_SESSION['marketplace_msg']); ?></p><?php endif; ?>
<section class="chatbox"><div class="messages" id="messages"><?php if(!$mensajes): ?><p class="muted">Aún no hay mensajes. Puedes comenzar la conversación para acordar los detalles del servicio.</p><?php else: foreach($mensajes as $m): ?><article class="msg <?php echo (int)$m['remitente_id']===$uid?'mine':''; ?>"><strong><?php echo cc_chat_h(trim(($m['nombre']??'').' '.($m['apellido']??''))); ?><?php echo (int)$m['remitente_id']===$uid?' (tú)':''; ?></strong><div style="white-space:pre-wrap;margin-top:6px"><?php echo cc_chat_h($m['mensaje']); ?></div><small><?php echo cc_chat_h($m['creado_en']); ?></small></article><?php endforeach; endif; ?></div><form class="field" method="post" action="<?php echo URLROOT.'/marketplace/enviarMensaje/'.(int)$c['id']; ?>"><label for="mensaje">Escribe un mensaje</label><textarea id="mensaje" name="mensaje" maxlength="5000" required placeholder="Consulta dudas, acuerda entregables y coordina el servicio..."></textarea><button class="send" type="submit">Enviar mensaje</button></form></section></main><script>const box=document.getElementById('messages');if(box)box.scrollTop=box.scrollHeight;</script></body></html>
